def calculate_shipping_cost(weight, destination):
    """
    Calculates the shipping cost based on the package weight and destination.

    :param weight: The weight of the package in pounds.
    :param destination: The destination country (as a string).
    :return: The shipping cost as an integer.
    """

    # Define the shipping rates for each weight and destination
    shipping_rates = {
        "domestic": {
            "under_1lb": 2,
            "1lb_5lb": 3,
            "5lb_10lb": 5,
            "over_10lb": 10
        },
        "international": {
            "under_1lb": 50,
            "1lb_5lb": 10,
            "5lb_10lb": 15,
            "over_10lb": 20
        }
    }

    # Determine the shipping cost based on the weight and destination
    if destination == "domestic":
        if weight < 1:
            return shipping_rates["domestic"]["under_1lb"]
        elif weight < 5:
            return shipping_rates["domestic"]["1lb_5lb"]
        elif weight < 10:
            return shipping_rates["domestic"]["5lb_10lb"]
        else:
            return shipping_rates["domestic"]["over_10lb"]
    else:
        return shipping_rates["international"]["under_1lb"]

# Example usage
weight = 10
destination = "International"
